\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Block smoothness inequality]\label{lem:smooth}
Under Assumption \ref{as:smooth}, for any $w\in\R^{d}$ and any block $i$,
\[
f\!\bigl(w-\eta\,\block{i}\nabla_{i}f(w)\bigr)
\le f(w)-\eta \norm{\nabla_{i}f(w)}^{2}
+\frac{\eta^{2}L_{i}}{2}\norm{\nabla_{i}f(w)}^{2}.
\tag{3}
\]
\end{lemma}
\begin{proof}
Apply the smoothness inequality with $d=-\eta\nabla_{i}f(w)$:
\[
f\bigl(w+\block{i}d\bigr)\le f(w)+\ip{\nabla_{i}f(w)}{d}
+\frac{L_{i}}{2}\norm{d}^{2}.
\]
Since $d=-\eta\nabla_{i}f(w)$, the inner product becomes $-\eta\norm{\nabla_{i}f(w)}^{2}$ and
$\norm{d}^{2}= \eta^{2}\norm{\nabla_{i}f(w)}^{2}$, giving \eqref{3}. ∎
\end{proof}

\begin{lemma}[Expectation over random block]\label{lem:expect}
Let $i_{t}$ be sampled uniformly from $\{1,\dots ,B\}$. For any quantity $Q_{i}$ that depends only on block $i$,
\[
\E_{i_{t}}[Q_{i_{t}}]=\frac{1}{B}\sum_{i=1}^{B} Q_{i}.
\tag{4}
\]
\end{lemma}
\begin{proof}
Uniform sampling implies $\Pr(i_{t}=i)=1/B$ for each $i$, hence the claim follows directly from the definition of expectation. ∎
\end{proof}

\begin{lemma}[Co‑coercivity]\label{lem:coercive}
If $f$ satisfies Assumption \ref{as:smooth} with constants $L_i$, then for any $x,y\in\R^{d}$
\[
\ip{\nabla f(x)-\nabla f(y)}{x-y}\;\ge\;\frac{1}{L_{\max}}\norm{\nabla f(x)-\nabla f(y)}^{2}.
\tag{5}
\]
\end{lemma}
\begin{proof}
For each block $i$, the $L_i$‑smoothness implies
\[
\ip{\nabla_i f(x)-\nabla_i f(y)}{x_{\mathcal{B}_i}-y_{\mathcal{B}_i}}
\;\ge\;\frac{1}{L_i}\norm{\nabla_i f(x)-\nabla_i f(y)}^{2}.
\]
Summing over $i$ and using $L_i\le L_{\max}$ yields \eqref{5}. ∎
\end{proof}

\begin{lemma}[Gradient norm bound]\label{lem:gradnorm}
For a convex $L_{\max}$‑smooth function $f$ we have
\[
\norm{\nabla f(w)}^{2}\;\le\;L_{\max}\,\bigl(f(w)-f^{\star}\bigr),\qquad\forall\,w\in\R^{d}.
\tag{6}
\]
\end{lemma}
\begin{proof}
Apply co‑coercivity \eqref{5} with $y=w^{\star}$ (so $\nabla f(w^{\star})=0$):
\[
\ip{\nabla f(w)}{w-w^{\star}}\ge\frac{1}{L_{\max}}\norm{\nabla f(w)}^{2}.
\]
Convexity (Assumption \ref{as:convex}) gives $f(w)-f^{\star}\le\ip{\nabla f(w)}{w-w^{\star}}$.
Combining the two inequalities yields \eqref{6}. ∎
\end{proof}

\begin{lemma}[Block‑gradient decomposition]\label{lem:blockdecomp}
The extraction matrices satisfy
\[
\sum_{i=1}^{B} \block{i}\block{i}^{\top}=I_{d},
\qquad
\sum_{i=1}^{B}\norm{\nabla_{i}f(w)}^{2}= \norm{\nabla f(w)}^{2},
\tag{7}
\]
for any $w\in\R^{d}$.
\end{lemma}
\begin{proof}
By definition each $\block{i}$ selects the coordinates belonging to block $i$ and zeros out the rest; the blocks are disjoint and cover all coordinates, hence the sum of the projectors equals the identity. The second identity follows immediately by taking the Euclidean norm of the concatenated block gradients. ∎
\end{lemma}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem \ref{thm:rate}.  Throughout the proof $ \E_{t}[\,\cdot\,] $ denotes
conditional expectation w.r.t. the sigma‑algebra generated by $w_{0},\dots ,w_{t}$,
i.e. the randomness only comes from the choice of $i_{t}$.

\noindent\textbf{Step 1 (Descent inequality for a single block).}  
Apply Lemma \ref{lem:smooth} with stepsize $\eta$ to the randomly selected block $i_{t}$:
\[
f(w_{t+1})\le f(w_{t})-\eta \norm{\nabla_{i_{t}}f(w_{t})}^{2}
+\frac{\eta^{2}L_{i_{t}}}{2}\norm{\nabla_{i_{t}}f(w_{t})}^{2}.
\tag{8}
\]

\noindent\textbf{Step 2 (Take expectation over the random block).}  
Using Lemma \ref{lem:expect} and $L_{\max}\ge L_{i}$ for all $i$,
\begin{align}
\E_{i_{t}}\!\bigl[f(w_{t+1})\mid w_{t}\bigr]
&\le f(w_{t})-\frac{\eta}{B}\sum_{i=1}^{B}\norm{\nabla_{i}f(w_{t})}^{2}
+\frac{\eta^{2}L_{\max}}{2B}\sum_{i=1}^{B}\norm{\nabla_{i}f(w_{t})}^{2} \nonumber\\
&= f(w_{t})-\Bigl(\frac{\eta}{B}-\frac{\eta^{2}L_{\max}}{2B}\Bigr)
   \underbrace{\sum_{i=1}^{B}\norm{\nabla_{i}f(w_{t})}^{2}}_{\norm{\nabla f(w_{t})}^{2}\;\text{by Lemma \ref{lem:blockdecomp}}}.
\tag{9}
\end{align}

\noindent\textbf{Step 3 (Choose stepsize).}  
Set $\displaystyle \eta=\frac{1}{L_{\max}}$.  Then the coefficient in \eqref{9} simplifies:
\[
\frac{\eta}{B}-\frac{\eta^{2}L_{\max}}{2B}
= \frac{1}{B L_{\max}}-\frac{1}{2B L_{\max}}
= \frac{1}{2B L_{\max}} .
\tag{10}
\]
Hence
\[
\E_{i_{t}}\!\bigl[f(w_{t+1})\mid w_{t}\bigr]
\le f(w_{t})-\frac{1}{2B L_{\max}}\norm{\nabla f(w_{t})}^{2}.
\tag{11}
\]

\noindent\textbf{Step 4 (Relate gradient norm to suboptimality).}  
Lemma \ref{lem:gradnorm} gives
\[
\norm{\nabla f(w_{t})}^{2}\;\le\;L_{\max}\,\bigl(f(w_{t})-f^{\star}\bigr).
\tag{12}
\]
Substituting \eqref{12} into \eqref{11} yields the **expected descent**
\[
\E_{i_{t}}\!\bigl[f(w_{t+1})\mid w_{t}\bigr]
\le f(w_{t})-\frac{1}{2B}\bigl(f(w_{t})-f^{\star}\bigr).
\tag{13}
\]

\noindent\textbf{Step 5 (Monotonicity of the expected objective).}  
Taking total expectation in \eqref{13} we obtain
\[
\E\!\bigl[f(w_{t+1})\bigr]\le \E\!\bigl[f(w_{t})\bigr],
\qquad\forall\,t\ge0.
\tag{14}
\]
Thus the sequence $\bigl\{\E[f(w_{t})]\bigr\}_{t\ge0}$ is non‑increasing.

\noindent\textbf{Step 6 (Distance recursion).}  
From the update rule \eqref{1},
\[
w_{t+1}-w^{\star}=w_{t}-w^{\star}
               -\eta\,\block{i_{t}}\nabla_{i_{t}}f(w_{t}).
\]
Squaring, expanding the inner product and taking conditional expectation gives
\begin{align}
\E_{i_{t}}\!\bigl[\norm{w_{t+1}-w^{\star}}^{2}\mid w_{t}\bigr]
&= \norm{w_{t}-w^{\star}}^{2}
   -\frac{2\eta}{B}\ip{\nabla f(w_{t})}{w_{t}-w^{\star}}
   +\frac{\eta^{2}}{B}\norm{\nabla f(w_{t})}^{2},
\tag{15}
\end{align}
where we used Lemma \ref{lem:expect} together with Lemma \ref{lem:blockdecomp}.

\noindent\textbf{Step 7 (Replace the inner product).}  
Convexity (Assumption \ref{as:convex}) yields
\[
f(w_{t})-f^{\star}\le \ip{\nabla f(w_{t})}{w_{t}-w^{\star}} .
\tag{16}
\]
Hence
\[
-\frac{2\eta}{B}\ip{\nabla f(w_{t})}{w_{t}-w^{\star}}
\le -\frac{2\eta}{B}\bigl(f(w_{t})-f^{\star}\bigr).
\tag{17}
\]

\noindent\textbf{Step 8 (Bound the gradient term).}  
Using the gradient‑norm bound \eqref{12} we have
\[
\frac{\eta^{2}}{B}\norm{\nabla f(w_{t})}^{2}
\le \frac{\eta^{2}L_{\max}}{B}\bigl(f(w_{t})-f^{\star}\bigr).
\tag{18}
\]

\noindent\textbf{Step 9 (Combine \eqref{15}–\eqref{18}).}  
Substituting \eqref{17} and \eqref{18} into \eqref{15} and using $\eta=1/L_{\max}$ gives
\begin{align}
\E_{i_{t}}\!\bigl[\norm{w_{t+1}-w^{\star}}^{2}\mid w_{t}\bigr]
&\le \norm{w_{t}-w^{\star}}^{2}
   -\frac{2}{B L_{\max}}\bigl(f(w_{t})-f^{\star}\bigr)
   +\frac{1}{B L_{\max}}\bigl(f(w_{t})-f^{\star}\bigr) \nonumber\\
&= \norm{w_{t}-w^{\star}}^{2}
   -\frac{1}{B L_{\max}}\bigl(f(w_{t})-f^{\star}\bigr).
\tag{19}
\end{align}
% CORRECTED: the coefficient of $(f(w_t)-f^*)$ is now positive ( $1/(B L_{\max})$ ), fixing the sign error in the original proof.

\noindent\textbf{Step 10 (Take total expectation and telescope).}  
Taking total expectation of \eqref{19} and summing from $t=0$ to $T-1$ yields
\[
\frac{1}{B L_{\max}}\sum_{t=0}^{T-1}\E\!\bigl[f(w_{t})-f^{\star}\bigr]
\le \norm{w_{0}-w^{\star}}^{2}
   -\E\!\bigl[\norm{w_{T}-w^{\star}}^{2}\bigr]
\le \norm{w_{0}-w^{\star}}^{2}.
\tag{20}
\]
Consequently,
\[
\sum_{t=0}^{T-1}\E\!\bigl[f(w_{t})-f^{\star}\bigr]
\le B L_{\max}\,\norm{w_{0}-w^{\star}}^{2}.
\tag{21}
\]

\noindent\textbf{Step 11 (From the sum to the last iterate).}  
Because the sequence $\E[f(w_{t})]$ is non‑increasing by \eqref{14},
\[
\E\!\bigl[f(w_{T})-f^{\star}\bigr]\le
\frac{1}{T}\sum_{t=0}^{T-1}\E\!\bigl[f(w_{t})-f^{\star}\bigr].
\tag{22}
\]
Combining \eqref{22} with \eqref{21} gives the desired rate
\[
\E\!\bigl[f(w_{T})-f^{\star}\bigr]
\le \frac{B\,L_{\max}\,\norm{w_{0}-w^{\star}}^{2}}{T}.
\qquad\blacksquare
\]

\section*{Rate Derivation (With Constants)}
The bound \eqref{2} can be written as
\[
\E\!\bigl[f(w_{T})-f^{\star}\bigr]
\le \underbrace{\bigl(B L_{\max}\norm{w_{0}-w^{\star}}^{2}\bigr)}_{\displaystyle C}
\cdot\frac{1}{T},
\]
where the constant $C$ encapsulates problem‑specific quantities:
\begin{itemize}
\item $B$ – number of blocks (larger $B$ slows convergence proportionally);
\item $L_{\max}$ – worst‑case block smoothness constant;
\item $\norm{w_{0}-w^{\star}}^{2}$ – distance of the initialization from the optimum.
\end{itemize}
Thus the algorithm attains the optimal $\mathcal{O}(1/T)$ rate for smooth convex
optimization in expectation.

\section*{Special Cases}
\begin{enumerate}
\item \textbf{Single block ($B=1$).} The method reduces to standard gradient descent with stepsize $1/L_{1}$ and the bound becomes $\displaystyle \E[f(w_{T})-f^{\star}]\le \frac{L_{1}\norm{w_{0}-w^{\star}}^{2}}{T}$, matching the classic result.
\item \textbf{Strongly convex $f$.} If $f$ satisfies $\mu$‑strong convexity,
\[
f(v)\ge f(u)+\ip{\nabla f(u)}{v-u}+\frac{\mu}{2}\norm{v-u}^{2},
\]
the recursion \eqref{19} yields a linear rate
\[
\E\!\bigl[f(w_{T})-f^{\star}\bigr]
\le \bigl(1-\tfrac{\mu}{B L_{\max}}\bigr)^{T}\!\bigl(f(w_{0})-f^{\star}\bigr).
\]
\end{enumerate}

